// D&D 3.5e Feats Index — SRD 3.5 only.
// Fabricated placeholder files removed (combat, skill, ability): every entry
// in them was invented filler ("Backstab", "Bird Call", skills-as-feats,
// "Ability Boost" feats) that does not exist in the 3.5 SRD. The keys are kept
// (as empty arrays) so downstream consumers retain a stable shape; the SRD has
// no separate combat/skill/ability feat categories.
//
// The remaining SRD feats are ENCODED, not hand-written: ./srd-feats.ts is
// generated by scripts/encode-35e-feats.mjs from the olimot/srd-v3.5-md feats
// chapter (the same source the srd:coverage denominator reads). The encoder
// skips any feat already present in the curated files, so the two sets are
// disjoint by construction and the hand-written entry always wins; the curated
// arrays are spread FIRST so their ordering is unchanged.

import { FeatDefinition } from '../../../../types/character-options/feats';
import { generalFeats } from './general';
import { metamagicFeats } from './metamagic';
import { itemCreationFeats } from './item-creation';
import { magicFeats } from './magic';
import { srd35eGeneralFeats, srd35eItemCreationFeats, srd35eMetamagicFeats } from './srd-feats';

export const dnd35eFeats = {
  general: [...generalFeats, ...srd35eGeneralFeats],
  metamagic: [...metamagicFeats, ...srd35eMetamagicFeats],
  itemCreation: [...itemCreationFeats, ...srd35eItemCreationFeats],
  combat: [] as FeatDefinition[],
  skill: [] as FeatDefinition[],
  ability: [] as FeatDefinition[],
  magic: magicFeats,
};

export const getFeat = (id: string) => {
  const allFeats = [
    ...dnd35eFeats.general,
    ...dnd35eFeats.metamagic,
    ...dnd35eFeats.itemCreation,
    ...dnd35eFeats.combat,
    ...dnd35eFeats.skill,
    ...dnd35eFeats.ability,
    ...dnd35eFeats.magic,
  ];
  return allFeats.find((f) => f.id === id);
};
